-- Reviewed visual guide sections. Exact legacy-text guards preserve authored edits.

-- No tier assignments, user content, or publication states are changed.

CREATE TABLE visual_guides_0035 (id TEXT PRIMARY KEY);

INSERT OR IGNORE INTO visual_guides_0035 SELECT 'guide-hotori' WHERE EXISTS (SELECT 1 FROM guide_sections WHERE id='hotori-build' AND replace(content_markdown,char(13),'')='## Дуга

Marching Beyond Time — сигнатурный вариант; Fluff of Fearlessness — альтернатива. Не сравнивайте варианты без учёта уровня наложения и условий команды.

## Консоль и картриджи

Lost Radiance («Утраченное сияние»): 2 части дают 10% урона Космоса, 4 части — 25% игнорирования защиты на 20 секунд после сверхспособности. Бонус консоли Хотори зависит от модулей типа III.

## Характеристики

Балансируйте шанс и урон критического попадания, бонус Космоса и атаку. При смене дуги меняется потребность в критическом шансе; универсального порога для всех сборок нет. Рекомендации рассчитаны на боевую роль и требуют сверки с выбранной дугой и пробуждениями.' AND json_extract(meta_json,'$.visual') IS NULL);

INSERT OR IGNORE INTO visual_guides_0035 SELECT 'guide-akane-0031' WHERE EXISTS (SELECT 1 FROM guide_sections WHERE id='guide-akane-0031-builds' AND replace(content_markdown,char(13),'')='Far Side of the Moon — сигнатурная дуга. Картридж Street Boxer; бонус консоли зависит от модулей типа III. Балансируйте атаку, критический шанс и критический урон с учётом бонусов дуги и картриджа.' AND json_extract(meta_json,'$.visual') IS NULL);

INSERT OR IGNORE INTO visual_guides_0035 SELECT 'guide-blackbird-0031' WHERE EXISTS (SELECT 1 FROM guide_sections WHERE id='guide-blackbird-0031-builds' AND replace(content_markdown,char(13),'')='Crime and Punishment — основной вариант дуги; Ravenous Blade — альтернатива. Картридж Devil’s Blood: Curse. Модули типа III дают критический шанс; учитывайте этот бонус при подборе критических статов. Интенсивность цикла важна для реакции Новы.' AND json_extract(meta_json,'$.visual') IS NULL);

INSERT OR IGNORE INTO visual_guides_0035 SELECT 'guide-iroi-0031' WHERE EXISTS (SELECT 1 FROM guide_sections WHERE id='guide-iroi-0031-builds' AND replace(content_markdown,char(13),'')='The Wrong Gate — основной выбор; Clear Skies — доступная альтернатива. Speedy Hedgehog помогает со сверхспособностью и командным усилением. Атака важна для её эффектов; энергию и лечение подбирайте под фактическую выживаемость отряда.' AND json_extract(meta_json,'$.visual') IS NULL);

INSERT OR IGNORE INTO visual_guides_0035 SELECT 'guide-linko-0031' WHERE EXISTS (SELECT 1 FROM guide_sections WHERE id='guide-linko-0031-builds' AND replace(content_markdown,char(13),'')='Voice of the Voyager — основной выбор дуги. Картридж Fireflies and the Forest; модули типа III дают критический шанс. Собирайте Линко как источник урона: атака, критические характеристики и бонус Анимы, с учётом выбранной дуги.' AND json_extract(meta_json,'$.visual') IS NULL);

INSERT OR IGNORE INTO visual_guides_0035 SELECT 'guide-zankou-0031' WHERE EXISTS (SELECT 1 FROM guide_sections WHERE id='guide-zankou-0031-builds' AND replace(content_markdown,char(13),'')='Ravenous Blade — основной выбор; Fluff of Finesse — альтернатива. Картридж Crimson: Twin Butterflies; при его отсутствии рассматривайте Shadow Creed. Модули типа III усиливают критический урон: балансируйте его с шансом критического попадания и атакой.' AND json_extract(meta_json,'$.visual') IS NULL);

