INSERT OR IGNORE INTO guide_sections (id,guide_id,title,section_type,content_markdown,position,meta_json) SELECT 'hotori-arcs-0035','guide-hotori','Лучшие дуги','best-arcs','',4,'{"visual":{"kind":"arcs","items":[{"id":"hotori-arcs-1","name":"Marching Beyond Time","imageUrl":"https://static.nanoka.cc/assets/nte/Game/UI/UI_Icon/Fork/1024/fork_Time.webp","description":"Даёт 16% атаки. После навыка перенаправления записывает до трёх действий перенаправления или поддержки союзников. Сверхспособность расходует записи: 24% критического урона сверхспособности и ещё по 8% за запись. Три записи дополнительно дают 12% игнорирования защиты на 70 секунд.","stats":[{"label":"Атака (ур. 80)","value":"570"},{"label":"Критический шанс (ур. 80)","value":"24%"}],"category":"signature","sourceUrl":"https://www.kaiden.gg/nte/characters/hotori/"},{"id":"hotori-arcs-2","name":"The Rain That Shook the World","imageUrl":"https://static.nanoka.cc/assets/nte/Game/UI/UI_Icon/Fork/1024/fork_worldrain.webp","description":"Увеличивает урон Космоса навыка перенаправления и сверхспособности на 30%. После навыка перенаправления даёт 36 силы цикла на 15 секунд.","stats":[{"label":"Атака (ур. 80)","value":"512"},{"label":"Критический шанс (ур. 80)","value":"22%"}],"category":"replacement","sourceUrl":"https://www.kaiden.gg/nte/characters/hotori/"}]},"reviewedAt":"2026-10-21"}' WHERE EXISTS (SELECT 1 FROM visual_guides_0035 WHERE id='guide-hotori') AND NOT EXISTS (SELECT 1 FROM guide_sections WHERE guide_id='guide-hotori' AND section_type='best-arcs');

INSERT OR IGNORE INTO guide_sections (id,guide_id,title,section_type,content_markdown,position,meta_json) SELECT 'hotori-cartridges-0035','guide-hotori','Лучшие картриджи','cartridges','',5,'{"visual":{"kind":"cartridges","items":[{"id":"hotori-cartridges-1","name":"Lost Radiance","imageUrl":"https://static.nanoka.cc/assets/nte/Game/UI/UI_Icon/kongmu/256/UI_YH_kongmuicon__03.webp","description":"","stats":[{"label":"2 предмета","value":"Урон Космоса +10%."},{"label":"4 предмета","value":"После сверхспособности игнорирует 25% защиты врага на 20 секунд. Эффект не складывается."}],"category":"signature","sourceUrl":"https://www.kaiden.gg/nte/characters/hotori/"},{"id":"hotori-cartridges-2","name":"Shadow Creed","imageUrl":"https://static.nanoka.cc/assets/nte/Game/UI/UI_Icon/kongmu/256/UI_YH_kongmuicon__39.webp","description":"","stats":[{"label":"2 предмета","value":"Атака +10%."},{"label":"4 предмета","value":"После навыка увеличивает атаку носителя на 25% на 20 секунд."}],"category":"replacement","sourceUrl":"https://www.kaiden.gg/nte/characters/hotori/"}]},"reviewedAt":"2026-10-21"}' WHERE EXISTS (SELECT 1 FROM visual_guides_0035 WHERE id='guide-hotori') AND NOT EXISTS (SELECT 1 FROM guide_sections WHERE guide_id='guide-hotori' AND section_type='cartridges');

INSERT OR IGNORE INTO guide_sections (id,guide_id,title,section_type,content_markdown,position,meta_json) SELECT 'hotori-skills-0035','guide-hotori','Приоритет прокачки навыков','skill-priority','',7,'{"visual":{"kind":"skills","items":[{"id":"hotori-skills-0","name":"Сверхспособность","description":"World''s Tide — одинаковый приоритет со следующим навыком.","imageUrl":"https://www.kaiden.gg/img/nte/UI/UI_Icon/Skill/Jin_UltraSkillA.webp","stats":[],"sourceUrl":"https://www.icy-veins.com/neverness-to-everness/hotori-guide-best-builds"},{"id":"hotori-skills-1","name":"Навык перенаправления","description":"Present Replay — одинаковый приоритет с предыдущим навыком.","imageUrl":"https://www.kaiden.gg/img/nte/UI/UI_Icon/Skill/Jin_Skill.webp","stats":[],"sourceUrl":"https://www.icy-veins.com/neverness-to-everness/hotori-guide-best-builds"},{"id":"hotori-skills-2","name":"Базовая атака","description":"Misty Moon Style","imageUrl":"https://www.kaiden.gg/img/nte/UI/UI_Icon/Skill/Jin_Melee.webp","stats":[],"sourceUrl":"https://www.icy-veins.com/neverness-to-everness/hotori-guide-best-builds"},{"id":"hotori-skills-3","name":"Навык поддержки","description":"Shopkeeper''s Authority","imageUrl":"https://www.kaiden.gg/img/nte/UI/UI_Icon/Skill/Jin_QTE.webp","stats":[],"sourceUrl":"https://www.icy-veins.com/neverness-to-everness/hotori-guide-best-builds"}]},"reviewedAt":"2026-10-21"}' WHERE EXISTS (SELECT 1 FROM visual_guides_0035 WHERE id='guide-hotori') AND NOT EXISTS (SELECT 1 FROM guide_sections WHERE guide_id='guide-hotori' AND section_type='skill-priority');

