UPDATE guide_sections SET section_type='sources',title='Архив сборки',updated_at=CURRENT_TIMESTAMP WHERE id='hotori-build' AND replace(content_markdown,char(13),'')='## Дуга

Marching Beyond Time — сигнатурный вариант; Fluff of Fearlessness — альтернатива. Не сравнивайте варианты без учёта уровня наложения и условий команды.

## Консоль и картриджи

Lost Radiance («Утраченное сияние»): 2 части дают 10% урона Космоса, 4 части — 25% игнорирования защиты на 20 секунд после сверхспособности. Бонус консоли Хотори зависит от модулей типа III.

## Характеристики

Балансируйте шанс и урон критического попадания, бонус Космоса и атаку. При смене дуги меняется потребность в критическом шансе; универсального порога для всех сборок нет. Рекомендации рассчитаны на боевую роль и требуют сверки с выбранной дугой и пробуждениями.' AND json_extract(meta_json,'$.visual') IS NULL AND EXISTS (SELECT 1 FROM visual_guides_0035 WHERE id='guide-hotori');

UPDATE guide_sections SET title='Базовая ротация',meta_json=json_set(meta_json,'$.visual',json('{"kind":"rotation","items":[{"id":"hotori-rotation-1","name":"Шаг 1","description":"Дождитесь достаточного запаса «Незакрытых часов» для навыка Хотори; ресурс накапливается со временем, а не от количества базовых атак.","imageUrl":"","stats":[]},{"id":"hotori-rotation-2","name":"Шаг 2","description":"Примените навык Хотори, открывающий окно записи.","imageUrl":"","stats":[]},{"id":"hotori-rotation-3","name":"Шаг 3","description":"В течение следующих 5 секунд используйте навыки поддержки или перенаправления разных союзников; записывается не более одного действия каждого персонажа.","imageUrl":"","stats":[]},{"id":"hotori-rotation-4","name":"Шаг 4","description":"Подготовьте командные усиления и дождитесь 120 единиц ресурса. Не пытайтесь запустить сверхспособность сразу после записи при неполной шкале.","imageUrl":"","stats":[]},{"id":"hotori-rotation-5","name":"Шаг 5","description":"Активируйте сверхспособность Хотори, чтобы воспроизвести запись и атаковать в остановке времени. Переключение персонажей в этом состоянии недоступно.","imageUrl":"","stats":[]},{"id":"hotori-rotation-6","name":"Шаг 6","description":"После завершения окна вернитесь к действиям союзников и подготовке следующей записи.","imageUrl":"","stats":[]}]}'),'$.legacyMarkdown',content_markdown),content_markdown='',updated_at=CURRENT_TIMESTAMP WHERE id='hotori-rotations' AND replace(content_markdown,char(13),'')='1. Дождитесь достаточного запаса «Незакрытых часов» для навыка Хотори; ресурс накапливается со временем, а не от количества базовых атак.
2. Примените навык Хотори, открывающий окно записи.
3. В течение следующих 5 секунд используйте навыки поддержки или перенаправления разных союзников; записывается не более одного действия каждого персонажа.
4. Подготовьте командные усиления и дождитесь 120 единиц ресурса. Не пытайтесь запустить сверхспособность сразу после записи при неполной шкале.
5. Активируйте сверхспособность Хотори, чтобы воспроизвести запись и атаковать в остановке времени. Переключение персонажей в этом состоянии недоступно.
6. После завершения окна вернитесь к действиям союзников и подготовке следующей записи.' AND json_extract(meta_json,'$.visual') IS NULL;

UPDATE guide_sections SET title='Советы и частые ошибки',content_markdown='- Не путайте три записываемых действия разных союзников с зарядами сигнатурной дуги.
- Сначала откройте окно записи навыком Хотори: действия до него не записываются.
- Повторное применение навыка заменяет предыдущую запись.
- Проверяйте готовность сверхспособности по шкале ресурса; базовые атаки не ускоряют её заполнение.
- Выбирайте пробуждения под задачу и бюджет, сверяя их эффекты в профиле. Не переносите расчёты для A6 и усиленной дуги на персонажа без вложений.',updated_at=CURRENT_TIMESTAMP WHERE id='hotori-mistakes' AND replace(content_markdown,char(13),'')='- Не путайте три записываемых действия разных союзников с зарядами сигнатурной дуги.
- Сначала откройте окно записи навыком Хотори: действия до него не записываются.
- Повторное применение навыка заменяет предыдущую запись.
- Проверяйте готовность сверхспособности по шкале ресурса; базовые атаки не ускоряют её заполнение.
- Выбирайте пробуждения под задачу и бюджет, сверяя их эффекты в профиле. Не переносите расчёты для A6 и усиленной дуги на персонажа без вложений.' AND json_extract(meta_json,'$.visual') IS NULL;

INSERT OR IGNORE INTO guide_sections (id,guide_id,title,section_type,content_markdown,position,meta_json) SELECT 'akane-arcs-0035','guide-akane-0031','Лучшие дуги','best-arcs','',4,'{"visual":{"kind":"arcs","items":[{"id":"akane-arcs-1","name":"Far Side of the Moon","imageUrl":"https://static.nanoka.cc/assets/nte/Game/UI/UI_Icon/Fork/1024/fork_prism.webp","description":"Даёт 15% критического шанса и 28% урона навыка перенаправления. После него на 15 секунд усиливает базовые атаки на 28% и урон Лакшаны на 20%.","stats":[{"label":"Атака (ур. 80)","value":"570"},{"label":"Критический урон (ур. 80)","value":"48%"}],"category":"signature","sourceUrl":"https://www.kaiden.gg/nte/characters/akane/"},{"name":"Fluff of Fleetness","category":"budget","stats":[{"label":"Атака (ур. 80)","value":"512"},{"label":"Критический урон (ур. 80)","value":"44%"}],"imageUrl":"https://static.nanoka.cc/assets/nte/Game/UI/UI_Icon/Fork/1024/fork_MotorCandy.webp","description":"На поле получает по 5% атаки каждую секунду, до пяти стаков. После ухода с поля стаки сбрасываются.","sourceUrl":"https://www.kaiden.gg/nte/characters/akane/","id":"akane-arcs-2"}]},"reviewedAt":"2026-10-21"}' WHERE EXISTS (SELECT 1 FROM visual_guides_0035 WHERE id='guide-akane-0031') AND NOT EXISTS (SELECT 1 FROM guide_sections WHERE guide_id='guide-akane-0031' AND section_type='best-arcs');

INSERT OR IGNORE INTO guide_sections (id,guide_id,title,section_type,content_markdown,position,meta_json) SELECT 'akane-cartridges-0035','guide-akane-0031','Лучшие картриджи','cartridges','',5,'{"visual":{"kind":"cartridges","items":[{"id":"akane-cartridges-1","name":"Street Boxer","imageUrl":"https://static.nanoka.cc/assets/nte/Game/UI/UI_Icon/kongmu/256/UI_YH_kongmuicon__01.webp","description":"","stats":[{"label":"2 предмета","value":"Урон Лакшаны +10%."},{"label":"4 предмета","value":"Даёт 14% критического шанса. После Реморы или Пятна в отряде даёт ещё 14% на 20 секунд."}],"category":"signature","sourceUrl":"https://neverness.gg/akane-rin-nte-build/"}]},"reviewedAt":"2026-10-21"}' WHERE EXISTS (SELECT 1 FROM visual_guides_0035 WHERE id='guide-akane-0031') AND NOT EXISTS (SELECT 1 FROM guide_sections WHERE guide_id='guide-akane-0031' AND section_type='cartridges');

UPDATE guide_sections SET title='Приоритет прокачки навыков',meta_json=json_set(meta_json,'$.visual',json('{"kind":"skills","items":[{"id":"akane-skills-0","name":"Базовая атака","description":"Stringblade","imageUrl":"https://www.kaiden.gg/img/nte/UI/UI_Icon/Skill/Chaos_Melee.webp","stats":[],"sourceUrl":"https://neverness.gg/akane-rin-nte-build/"},{"id":"akane-skills-1","name":"Сверхспособность","description":"Sonic Boom","imageUrl":"https://www.kaiden.gg/img/nte/UI/UI_Icon/Skill/Chaos_UltraSkill.webp","stats":[],"sourceUrl":"https://neverness.gg/akane-rin-nte-build/"},{"id":"akane-skills-2","name":"Навык перенаправления","description":"Rhythm Wave","imageUrl":"https://www.kaiden.gg/img/nte/UI/UI_Icon/Skill/Chaos_Skill.webp","stats":[],"sourceUrl":"https://neverness.gg/akane-rin-nte-build/"},{"id":"akane-skills-3","name":"Навык поддержки","description":"Altered Chord","imageUrl":"https://www.kaiden.gg/img/nte/UI/UI_Icon/Skill/Chaos_QTE.webp","stats":[],"sourceUrl":"https://neverness.gg/akane-rin-nte-build/"}]}'),'$.legacyMarkdown',content_markdown),content_markdown='',updated_at=CURRENT_TIMESTAMP WHERE id='guide-akane-0031-skill-priority' AND replace(content_markdown,char(13),'')='Базовая атака → сверхспособность → навык перенаправления → навык поддержки. Это порядок из стартового гайда Neverness.gg, а не подтверждённый расчётом универсальный оптимум.' AND json_extract(meta_json,'$.visual') IS NULL;

INSERT OR IGNORE INTO guide_sections (id,guide_id,title,section_type,content_markdown,position,meta_json) SELECT 'akane-stats-0035','guide-akane-0031','Основные статы','main-stats','',6,'{"visual":{"kind":"stats","items":[{"id":"akane-stats-0","name":"Критический шанс / урон","imageUrl":"","description":"Учитывайте бонусы дуги, консоли и отряда; итоговый шанс не должен превышать 100%.","stats":[]},{"id":"akane-stats-1","name":"Атака %","imageUrl":"","description":"","stats":[]},{"id":"akane-stats-2","name":"Бонус урона Лакшаны","imageUrl":"","description":"","stats":[]}]},"reviewedAt":"2026-10-21"}' WHERE EXISTS (SELECT 1 FROM visual_guides_0035 WHERE id='guide-akane-0031') AND NOT EXISTS (SELECT 1 FROM guide_sections WHERE guide_id='guide-akane-0031' AND section_type='main-stats');

UPDATE guide_sections SET section_type='sources',title='Архив сборки',updated_at=CURRENT_TIMESTAMP WHERE id='guide-akane-0031-builds' AND replace(content_markdown,char(13),'')='Far Side of the Moon — сигнатурная дуга. Картридж Street Boxer; бонус консоли зависит от модулей типа III. Балансируйте атаку, критический шанс и критический урон с учётом бонусов дуги и картриджа.' AND json_extract(meta_json,'$.visual') IS NULL AND EXISTS (SELECT 1 FROM visual_guides_0035 WHERE id='guide-akane-0031');

UPDATE guide_sections SET title='Базовая ротация',meta_json=json_set(meta_json,'$.visual',json('{"kind":"rotation","items":[{"id":"akane-rotation-1","name":"Шаг 1","description":"Подготовьте усиления и лечение союзников перед выходом Аканэ.","imageUrl":"","stats":[]},{"id":"akane-rotation-2","name":"Шаг 2","description":"Коротким нажатием Rhythm Wave поставьте Overtone на одну цель; удержанием создайте Reverb Field для группы.","imageUrl":"","stats":[]},{"id":"akane-rotation-3","name":"Шаг 3","description":"Базовыми атаками накопите 30 String Energy и используйте Synced Resonance, пока действует выбранная форма.","imageUrl":"","stats":[]},{"id":"akane-rotation-4","name":"Шаг 4","description":"Примените Sonic Boom; во второй половине Solo Cadenza повторно нажмите сверхспособность вручную.","imageUrl":"","stats":[]},{"id":"akane-rotation-5","name":"Шаг 5","description":"После окончания усилений обновите действия союзников и повторите цикл.","imageUrl":"","stats":[]}]}'),'$.legacyMarkdown',content_markdown),content_markdown='',updated_at=CURRENT_TIMESTAMP WHERE id='guide-akane-0031-rotations' AND replace(content_markdown,char(13),'')='1. Подготовьте усиления и лечение союзников перед выходом Аканэ.
2. Коротким нажатием Rhythm Wave поставьте Overtone на одну цель; удержанием создайте Reverb Field для группы.
3. Базовыми атаками накопите 30 String Energy и используйте Synced Resonance, пока действует выбранная форма.
4. Примените Sonic Boom; во второй половине Solo Cadenza повторно нажмите сверхспособность вручную.
5. После окончания усилений обновите действия союзников и повторите цикл.' AND json_extract(meta_json,'$.visual') IS NULL;

UPDATE guide_sections SET title='Советы и частые ошибки',content_markdown='Не ждите автоматической второй части сверхспособности. Выбор одиночной метки или поля зависит от числа целей.',updated_at=CURRENT_TIMESTAMP WHERE id='guide-akane-0031-tips' AND replace(content_markdown,char(13),'')='Не ждите автоматической второй части сверхспособности. Выбор одиночной метки или поля зависит от числа целей. Не переносите оценки других персонажей на Аканэ: её место в едином тир-листе пока не задано.' AND json_extract(meta_json,'$.visual') IS NULL;

INSERT OR IGNORE INTO guide_sections (id,guide_id,title,section_type,content_markdown,position,meta_json) SELECT 'blackbird-arcs-0035','guide-blackbird-0031','Лучшие дуги','best-arcs','',4,'{"visual":{"kind":"arcs","items":[{"id":"blackbird-arcs-1","name":"Crime and Punishment","imageUrl":"https://static.nanoka.cc/assets/nte/Game/UI/UI_Icon/Fork/1024/fork_twinbirds.webp","description":"Даёт 72 силы цикла и 20% урона Психеи. После сверхспособности на 15 секунд увеличивает критический урон отряда на 16%, а носителя — ещё на 32%.","stats":[{"label":"Атака (ур. 80)","value":"570"},{"label":"Критический шанс (ур. 80)","value":"24%"}],"category":"signature","sourceUrl":"https://www.kaiden.gg/nte/characters/blackbird/"},{"id":"blackbird-arcs-2","name":"Ravenous Blade","imageUrl":"https://static.nanoka.cc/assets/nte/Game/UI/UI_Icon/Fork/1024/fork_DemonBlade.webp","description":"Даёт 16% критического шанса. Урон Инкантации добавляет по 9% критического урона на 15 секунд, до семи стаков; новый стак появляется не чаще раза в 0,3 секунды.","stats":[{"label":"Атака (ур. 80)","value":"570"},{"label":"Критический шанс (ур. 80)","value":"24%"}],"category":"replacement","sourceUrl":"https://www.kaiden.gg/nte/characters/blackbird/"}]},"reviewedAt":"2026-10-21"}' WHERE EXISTS (SELECT 1 FROM visual_guides_0035 WHERE id='guide-blackbird-0031') AND NOT EXISTS (SELECT 1 FROM guide_sections WHERE guide_id='guide-blackbird-0031' AND section_type='best-arcs');

