UPDATE guide_sections SET title='Приоритет прокачки навыков',meta_json=json_set(meta_json,'$.visual',json('{"kind":"skills","items":[{"id":"blackbird-skills-0","name":"Сверхспособность","description":"Requies Animarum — одинаковый приоритет со следующим навыком.","imageUrl":"https://www.kaiden.gg/img/nte/UI/UI_Icon/Skill/BlackBird_UltraSkill.webp","stats":[],"sourceUrl":"https://www.icy-veins.com/neverness-to-everness/blackbird-guide-best-builds"},{"id":"blackbird-skills-1","name":"Базовая атака","description":"Fleeting Shadow — одинаковый приоритет с предыдущим навыком.","imageUrl":"https://www.kaiden.gg/img/nte/UI/UI_Icon/Skill/BlackBird_Melee.webp","stats":[],"sourceUrl":"https://www.icy-veins.com/neverness-to-everness/blackbird-guide-best-builds"},{"id":"blackbird-skills-2","name":"Навык перенаправления","description":"Netherplume Rite Для роли поддержки прокачивайте первым, затем сверхспособность.","imageUrl":"https://www.kaiden.gg/img/nte/UI/UI_Icon/Skill/BlackBird_Skill.webp","stats":[],"sourceUrl":"https://www.icy-veins.com/neverness-to-everness/blackbird-guide-best-builds"},{"id":"blackbird-skills-3","name":"Навык поддержки","description":"Judgment Upon Me","imageUrl":"https://www.kaiden.gg/img/nte/UI/UI_Icon/Skill/BlackBird_QTE.webp","stats":[],"sourceUrl":"https://www.icy-veins.com/neverness-to-everness/blackbird-guide-best-builds"}]}'),'$.legacyMarkdown',content_markdown),content_markdown='',updated_at=CURRENT_TIMESTAMP WHERE id='guide-blackbird-0031-skill-priority' AND replace(content_markdown,char(13),'')='Развивайте навыки под выбранную роль: базовые атаки для пребывания на поле, метку и сверхспособность для коротких выходов. Единого порядка для обеих сборок источник не устанавливает.' AND json_extract(meta_json,'$.visual') IS NULL;

INSERT OR IGNORE INTO guide_sections (id,guide_id,title,section_type,content_markdown,position,meta_json) SELECT 'blackbird-stats-0035','guide-blackbird-0031','Основные статы','main-stats','',6,'{"visual":{"kind":"stats","items":[{"id":"blackbird-stats-0","name":"Критический урон","imageUrl":"","description":"","stats":[]},{"id":"blackbird-stats-1","name":"Бонус урона Психеи","imageUrl":"","description":"","stats":[]},{"id":"blackbird-stats-2","name":"Атака %","imageUrl":"","description":"","stats":[]},{"id":"blackbird-stats-3","name":"Критический шанс","imageUrl":"","description":"Учитывайте бонусы дуги, консоли и отряда; итоговый шанс не должен превышать 100%.","stats":[]}]},"reviewedAt":"2026-10-21"}' WHERE EXISTS (SELECT 1 FROM visual_guides_0035 WHERE id='guide-blackbird-0031') AND NOT EXISTS (SELECT 1 FROM guide_sections WHERE guide_id='guide-blackbird-0031' AND section_type='main-stats');

UPDATE guide_sections SET section_type='sources',title='Архив сборки',updated_at=CURRENT_TIMESTAMP WHERE id='guide-blackbird-0031-builds' AND replace(content_markdown,char(13),'')='Crime and Punishment — основной вариант дуги; Ravenous Blade — альтернатива. Картридж Devil’s Blood: Curse. Модули типа III дают критический шанс; учитывайте этот бонус при подборе критических статов. Интенсивность цикла важна для реакции Новы.' AND json_extract(meta_json,'$.visual') IS NULL AND EXISTS (SELECT 1 FROM visual_guides_0035 WHERE id='guide-blackbird-0031');

UPDATE guide_sections SET title='Базовая ротация',meta_json=json_set(meta_json,'$.visual',json('{"kind":"rotation","items":[{"id":"blackbird-rotation-1","name":"Шаг 1","description":"Подготовьте усиления союзников и реакцию Хаоса с Психикой.","imageUrl":"","stats":[]},{"id":"blackbird-rotation-2","name":"Шаг 2","description":"Навыком Блэкбёрд отметьте цель, затем примените сверхспособность для командного усиления атаки.","imageUrl":"","stats":[]},{"id":"blackbird-rotation-3","name":"Шаг 3","description":"Для короткого выхода переключитесь на союзника: его атаки запускают удары птицы по отмеченной цели.","imageUrl":"","stats":[]},{"id":"blackbird-rotation-4","name":"Шаг 4","description":"Для игры на поле останьтесь в форме Witch of Deliverance, завершите цепочку базовых атак и используйте завершающую атаку.","imageUrl":"","stats":[]},{"id":"blackbird-rotation-5","name":"Шаг 5","description":"Обновляйте метку и усиления перед следующим окном Новы.","imageUrl":"","stats":[]}]}'),'$.legacyMarkdown',content_markdown),content_markdown='',updated_at=CURRENT_TIMESTAMP WHERE id='guide-blackbird-0031-rotations' AND replace(content_markdown,char(13),'')='1. Подготовьте усиления союзников и реакцию Хаоса с Психикой.
2. Навыком Блэкбёрд отметьте цель, затем примените сверхспособность для командного усиления атаки.
3. Для короткого выхода переключитесь на союзника: его атаки запускают удары птицы по отмеченной цели.
4. Для игры на поле останьтесь в форме Witch of Deliverance, завершите цепочку базовых атак и используйте завершающую атаку.
5. Обновляйте метку и усиления перед следующим окном Новы.' AND json_extract(meta_json,'$.visual') IS NULL;

UPDATE guide_sections SET title='Советы и частые ошибки',content_markdown='Не смешивайте условия сборки на поле и из резерва. Сигнатурная дуга и A1 заметно меняют результат; сравнивайте команды при одинаковых вложениях.',updated_at=CURRENT_TIMESTAMP WHERE id='guide-blackbird-0031-tips' AND replace(content_markdown,char(13),'')='Не смешивайте условия сборки на поле и из резерва. Сигнатурная дуга и A1 заметно меняют результат; сравнивайте команды при одинаковых вложениях.' AND json_extract(meta_json,'$.visual') IS NULL;

INSERT OR IGNORE INTO guide_sections (id,guide_id,title,section_type,content_markdown,position,meta_json) SELECT 'iroi-arcs-0035','guide-iroi-0031','Лучшие дуги','best-arcs','',4,'{"visual":{"kind":"arcs","items":[{"id":"iroi-arcs-1","name":"The Wrong Gate","imageUrl":"https://static.nanoka.cc/assets/nte/Game/UI/UI_Icon/Fork/1024/fork_Door.webp","description":"Даёт 16% атаки. Лечение на 20 секунд усиливает урон Анимы носителя на 30%, а урон всех союзников — на 15%. Одинаковые эффекты не складываются.","stats":[{"label":"Атака (ур. 80)","value":"570"},{"label":"Бонус атаки (ур. 80)","value":"30%"}],"category":"signature","sourceUrl":"https://www.kaiden.gg/nte/characters/iroi/"},{"name":"Clear Skies","category":"budget","stats":[{"label":"Атака (ур. 80)","value":"475"},{"label":"Бонус атаки (ур. 80)","value":"25%"}],"imageUrl":"https://static.nanoka.cc/assets/nte/Game/UI/UI_Icon/Fork/1024/fork_PaperPlane.webp","description":"Увеличивает урон Анимы навыка перенаправления и сверхспособности на 20%.","sourceUrl":"https://www.kaiden.gg/nte/characters/iroi/","id":"iroi-arcs-2"}]},"reviewedAt":"2026-10-21"}' WHERE EXISTS (SELECT 1 FROM visual_guides_0035 WHERE id='guide-iroi-0031') AND NOT EXISTS (SELECT 1 FROM guide_sections WHERE guide_id='guide-iroi-0031' AND section_type='best-arcs');

INSERT OR IGNORE INTO guide_sections (id,guide_id,title,section_type,content_markdown,position,meta_json) SELECT 'iroi-cartridges-0035','guide-iroi-0031','Лучшие картриджи','cartridges','',5,'{"visual":{"kind":"cartridges","items":[{"id":"iroi-cartridges-1","name":"Speedy Hedgehog","imageUrl":"https://static.nanoka.cc/assets/nte/Game/UI/UI_Icon/kongmu/256/UI_YH_kongmuicon__35.webp","description":"","stats":[{"label":"2 предмета","value":"Восстановление энергии +12%."},{"label":"4 предмета","value":"После сверхспособности увеличивает атаку союзников на 15% на 20 секунд. Эффект не складывается."}],"category":"signature","sourceUrl":"https://www.kaiden.gg/nte/characters/iroi/"},{"id":"iroi-cartridges-2","name":"Fireflies and the Forest","imageUrl":"https://static.nanoka.cc/assets/nte/Game/UI/UI_Icon/kongmu/256/UI_YH_kongmuicon__09.webp","description":"","stats":[{"label":"2 предмета","value":"Урон Анимы +10%."},{"label":"4 предмета","value":"Когда отряд наносит ближайшему врагу урон Анимы, носитель получает по 8% критического урона, до семи стаков. Каждый длится 10 секунд; эффект работает из резерва."}],"category":"replacement","sourceUrl":"https://www.kaiden.gg/nte/characters/iroi/"}]},"reviewedAt":"2026-10-21"}' WHERE EXISTS (SELECT 1 FROM visual_guides_0035 WHERE id='guide-iroi-0031') AND NOT EXISTS (SELECT 1 FROM guide_sections WHERE guide_id='guide-iroi-0031' AND section_type='cartridges');

UPDATE guide_sections SET title='Приоритет прокачки навыков',meta_json=json_set(meta_json,'$.visual',json('{"kind":"skills","items":[{"id":"iroi-skills-0","name":"Навык перенаправления","description":"Future Self Continuity","imageUrl":"https://www.kaiden.gg/img/nte/UI/UI_Icon/Skill/Oneiroi_Skill.webp","stats":[],"sourceUrl":"https://www.icy-veins.com/neverness-to-everness/iroi-guide-best-builds"},{"id":"iroi-skills-1","name":"Сверхспособность","description":"3.8-Billion-Year Mirage","imageUrl":"https://www.kaiden.gg/img/nte/UI/UI_Icon/Skill/Oneiroi_UltraSkill.webp","stats":[],"sourceUrl":"https://www.icy-veins.com/neverness-to-everness/iroi-guide-best-builds"},{"id":"iroi-skills-2","name":"Базовая атака","description":"Collaboration","imageUrl":"https://www.kaiden.gg/img/nte/UI/UI_Icon/Skill/Oneiroi_Melee.webp","stats":[],"sourceUrl":"https://www.icy-veins.com/neverness-to-everness/iroi-guide-best-builds"},{"id":"iroi-skills-3","name":"Навык поддержки","description":"Bang!","imageUrl":"https://www.kaiden.gg/img/nte/UI/UI_Icon/Skill/Oneiroi_QTE.webp","stats":[],"sourceUrl":"https://www.icy-veins.com/neverness-to-everness/iroi-guide-best-builds"}]}'),'$.legacyMarkdown',content_markdown),content_markdown='',updated_at=CURRENT_TIMESTAMP WHERE id='guide-iroi-0031-skill-priority' AND replace(content_markdown,char(13),'')='В первую очередь проверяйте развитие сверхспособности и навыка перенаправления, затем навыка поддержки. При смене задачи с лечения на личный урон приоритеты могут измениться.' AND json_extract(meta_json,'$.visual') IS NULL;

INSERT OR IGNORE INTO guide_sections (id,guide_id,title,section_type,content_markdown,position,meta_json) SELECT 'iroi-stats-0035','guide-iroi-0031','Основные статы','main-stats','',6,'{"visual":{"kind":"stats","items":[{"id":"iroi-stats-0","name":"Атака %","imageUrl":"","description":"Усиливает лечение и личный урон. Усиление атаки союзников зависит от базовой атаки персонажа и дуги, а не от статов модулей.","stats":[]},{"id":"iroi-stats-1","name":"Бонус урона Анимы","imageUrl":"","description":"","stats":[]},{"id":"iroi-stats-2","name":"Бонус лечения","imageUrl":"","description":"Выбирайте, если отряду не хватает лечения.","stats":[]}]},"reviewedAt":"2026-10-21"}' WHERE EXISTS (SELECT 1 FROM visual_guides_0035 WHERE id='guide-iroi-0031') AND NOT EXISTS (SELECT 1 FROM guide_sections WHERE guide_id='guide-iroi-0031' AND section_type='main-stats');

UPDATE guide_sections SET section_type='sources',title='Архив сборки',updated_at=CURRENT_TIMESTAMP WHERE id='guide-iroi-0031-builds' AND replace(content_markdown,char(13),'')='The Wrong Gate — основной выбор; Clear Skies — доступная альтернатива. Speedy Hedgehog помогает со сверхспособностью и командным усилением. Атака важна для её эффектов; энергию и лечение подбирайте под фактическую выживаемость отряда.' AND json_extract(meta_json,'$.visual') IS NULL AND EXISTS (SELECT 1 FROM visual_guides_0035 WHERE id='guide-iroi-0031');

UPDATE guide_sections SET title='Базовая ротация',meta_json=json_set(meta_json,'$.visual',json('{"kind":"rotation","items":[{"id":"iroi-rotation-1","name":"Шаг 1","description":"Используйте навык Ирой до выхода основного ДД, чтобы подготовить Regression и связанные усиления.","imageUrl":"","stats":[]},{"id":"iroi-rotation-2","name":"Шаг 2","description":"Переключитесь на персонажей реакций и обновите командные усиления.","imageUrl":"","stats":[]},{"id":"iroi-rotation-3","name":"Шаг 3","description":"Проведите окно урона основного ДД, пока Ирой поддерживает его из резерва.","imageUrl":"","stats":[]},{"id":"iroi-rotation-4","name":"Шаг 4","description":"Возвращайтесь к Ирой для обновления навыка; выбирайте применение сверхспособности по состоянию команды и ресурсу Imagination.","imageUrl":"","stats":[]},{"id":"iroi-rotation-5","name":"Шаг 5","description":"Сохраняйте возможность восстановления союзника через сверхспособность, когда сработала Regression.","imageUrl":"","stats":[]}]}'),'$.legacyMarkdown',content_markdown),content_markdown='',updated_at=CURRENT_TIMESTAMP WHERE id='guide-iroi-0031-rotations' AND replace(content_markdown,char(13),'')='1. Используйте навык Ирой до выхода основного ДД, чтобы подготовить Regression и связанные усиления.
2. Переключитесь на персонажей реакций и обновите командные усиления.
3. Проведите окно урона основного ДД, пока Ирой поддерживает его из резерва.
4. Возвращайтесь к Ирой для обновления навыка; выбирайте применение сверхспособности по состоянию команды и ресурсу Imagination.
5. Сохраняйте возможность восстановления союзника через сверхспособность, когда сработала Regression.' AND json_extract(meta_json,'$.visual') IS NULL;

UPDATE guide_sections SET title='Советы и частые ошибки',content_markdown='Regression — ограниченная страховка, а не постоянная неуязвимость. Не тратьте всё время на поле на Ирой, если отряду нужны её лечение и усиления.',updated_at=CURRENT_TIMESTAMP WHERE id='guide-iroi-0031-tips' AND replace(content_markdown,char(13),'')='Regression — ограниченная страховка, а не постоянная неуязвимость. Не тратьте всё время на поле на Ирой, если отряду нужны её лечение и усиления.' AND json_extract(meta_json,'$.visual') IS NULL;

INSERT OR IGNORE INTO guide_sections (id,guide_id,title,section_type,content_markdown,position,meta_json) SELECT 'linko-arcs-0035','guide-linko-0031','Лучшие дуги','best-arcs','',4,'{"visual":{"kind":"arcs","items":[{"id":"linko-arcs-1","name":"Voice of the Voyager","imageUrl":"https://static.nanoka.cc/assets/nte/Game/UI/UI_Icon/Fork/1024/fork_GoldRecord.webp","description":"Даёт 24% атаки и 66% критического урона навыка поддержки. Сработавший навык поддержки усиливает критический урон сверхспособности на 22% на 3 секунды, до трёх стаков.","stats":[{"label":"Атака (ур. 80)","value":"570"},{"label":"Критический шанс (ур. 80)","value":"24%"}],"category":"signature","sourceUrl":"https://www.kaiden.gg/nte/characters/linko/"},{"id":"linko-arcs-2","name":"Ready-Ready","imageUrl":"https://static.nanoka.cc/assets/nte/Game/UI/UI_Icon/Fork/1024/fork_TigerTally.webp","description":"Даёт 15% атаки. Навык перенаправления или сверхспособность на 15 секунд усиливает базовые атаки и критический ответ на 15%, до двух стаков. Применение обоих навыков за 15 секунд дополнительно даёт 10% урона по боссам на 10 секунд.","stats":[{"label":"Атака (ур. 80)","value":"570"},{"label":"Критический шанс (ур. 80)","value":"24%"}],"category":"replacement","sourceUrl":"https://www.kaiden.gg/nte/characters/linko/"}]},"reviewedAt":"2026-10-21"}' WHERE EXISTS (SELECT 1 FROM visual_guides_0035 WHERE id='guide-linko-0031') AND NOT EXISTS (SELECT 1 FROM guide_sections WHERE guide_id='guide-linko-0031' AND section_type='best-arcs');

INSERT OR IGNORE INTO guide_sections (id,guide_id,title,section_type,content_markdown,position,meta_json) SELECT 'linko-cartridges-0035','guide-linko-0031','Лучшие картриджи','cartridges','',5,'{"visual":{"kind":"cartridges","items":[{"id":"linko-cartridges-1","name":"Fireflies and the Forest","imageUrl":"https://static.nanoka.cc/assets/nte/Game/UI/UI_Icon/kongmu/256/UI_YH_kongmuicon__09.webp","description":"","stats":[{"label":"2 предмета","value":"Урон Анимы +10%."},{"label":"4 предмета","value":"Когда отряд наносит ближайшему врагу урон Анимы, носитель получает по 8% критического урона, до семи стаков. Каждый длится 10 секунд; эффект работает из резерва."}],"category":"signature","sourceUrl":"https://www.kaiden.gg/nte/characters/linko/"}]},"reviewedAt":"2026-10-21"}' WHERE EXISTS (SELECT 1 FROM visual_guides_0035 WHERE id='guide-linko-0031') AND NOT EXISTS (SELECT 1 FROM guide_sections WHERE guide_id='guide-linko-0031' AND section_type='cartridges');

UPDATE guide_sections SET title='Приоритет прокачки навыков',meta_json=json_set(meta_json,'$.visual',json('{"kind":"skills","items":[{"id":"linko-skills-0","name":"Навык поддержки","description":"Spectral Cross","imageUrl":"https://www.kaiden.gg/img/nte/UI/UI_Icon/Skill/Linko_QTE.webp","stats":[],"sourceUrl":"https://www.icy-veins.com/neverness-to-everness/linko-guide-best-builds"},{"id":"linko-skills-1","name":"Сверхспособность","description":"Oversync","imageUrl":"https://www.kaiden.gg/img/nte/UI/UI_Icon/Skill/Linko_UltraSkill.webp","stats":[],"sourceUrl":"https://www.icy-veins.com/neverness-to-everness/linko-guide-best-builds"},{"id":"linko-skills-2","name":"Базовая атака","description":"Poltergeist CQC","imageUrl":"https://www.kaiden.gg/img/nte/UI/UI_Icon/Skill/Linko_Melee.webp","stats":[],"sourceUrl":"https://www.icy-veins.com/neverness-to-everness/linko-guide-best-builds"},{"id":"linko-skills-3","name":"Навык перенаправления","description":"Full-Frequency Pulse","imageUrl":"https://www.kaiden.gg/img/nte/UI/UI_Icon/Skill/Linko_Skill.webp","stats":[],"sourceUrl":"https://www.icy-veins.com/neverness-to-everness/linko-guide-best-builds"}]}'),'$.legacyMarkdown',content_markdown),content_markdown='',updated_at=CURRENT_TIMESTAMP WHERE id='guide-linko-0031-skill-priority' AND replace(content_markdown,char(13),'')='Навык поддержки Full-Frequency Pulse → сверхспособность Oversync → Spectral Cross → базовая атака. Проверяйте оба пассивных усиления последующих атак при развитии персонажа.' AND json_extract(meta_json,'$.visual') IS NULL;

INSERT OR IGNORE INTO guide_sections (id,guide_id,title,section_type,content_markdown,position,meta_json) SELECT 'linko-stats-0035','guide-linko-0031','Основные статы','main-stats','',6,'{"visual":{"kind":"stats","items":[{"id":"linko-stats-0","name":"Критический шанс","imageUrl":"","description":"Учитывайте бонусы дуги, консоли и отряда; итоговый шанс не должен превышать 100%.","stats":[]},{"id":"linko-stats-1","name":"Критический урон","imageUrl":"","description":"","stats":[]},{"id":"linko-stats-2","name":"Атака %","imageUrl":"","description":"","stats":[]},{"id":"linko-stats-3","name":"Бонус урона Анимы","imageUrl":"","description":"","stats":[]}]},"reviewedAt":"2026-10-21"}' WHERE EXISTS (SELECT 1 FROM visual_guides_0035 WHERE id='guide-linko-0031') AND NOT EXISTS (SELECT 1 FROM guide_sections WHERE guide_id='guide-linko-0031' AND section_type='main-stats');

UPDATE guide_sections SET section_type='sources',title='Архив сборки',updated_at=CURRENT_TIMESTAMP WHERE id='guide-linko-0031-builds' AND replace(content_markdown,char(13),'')='Voice of the Voyager — основной выбор дуги. Картридж Fireflies and the Forest; модули типа III дают критический шанс. Собирайте Линко как источник урона: атака, критические характеристики и бонус Анимы, с учётом выбранной дуги.' AND json_extract(meta_json,'$.visual') IS NULL AND EXISTS (SELECT 1 FROM visual_guides_0035 WHERE id='guide-linko-0031');

UPDATE guide_sections SET title='Базовая ротация',meta_json=json_set(meta_json,'$.visual',json('{"kind":"rotation","items":[{"id":"linko-rotation-1","name":"Шаг 1","description":"Сначала примените усиления Сакири; если в команде Ирой, заранее используйте её навык.","imageUrl":"","stats":[]},{"id":"linko-rotation-2","name":"Шаг 2","description":"Линко накопите Modulation базовыми атаками.","imageUrl":"","stats":[]},{"id":"linko-rotation-3","name":"Шаг 3","description":"Примените Full-Frequency Pulse и выберите основного ДД для синхронизированного удара.","imageUrl":"","stats":[]},{"id":"linko-rotation-4","name":"Шаг 4","description":"Активируйте Oversync и используйте доступные навыки поддержки внутри поля.","imageUrl":"","stats":[]},{"id":"linko-rotation-5","name":"Шаг 5","description":"Передайте поле основному ДД и проведите его окно урона; затем обновите усиления.","imageUrl":"","stats":[]}]}'),'$.legacyMarkdown',content_markdown),content_markdown='',updated_at=CURRENT_TIMESTAMP WHERE id='guide-linko-0031-rotations' AND replace(content_markdown,char(13),'')='1. Сначала примените усиления Сакири; если в команде Ирой, заранее используйте её навык.
2. Линко накопите Modulation базовыми атаками.
3. Примените Full-Frequency Pulse и выберите основного ДД для синхронизированного удара.
4. Активируйте Oversync и используйте доступные навыки поддержки внутри поля.
5. Передайте поле основному ДД и проведите его окно урона; затем обновите усиления.' AND json_extract(meta_json,'$.visual') IS NULL;

UPDATE guide_sections SET title='Советы и частые ошибки',content_markdown='Синхронизированный удар использует характеристики Линко. Не считайте её A0 эквивалентом A5: возможность запуска цикла меняется с пробуждениями.',updated_at=CURRENT_TIMESTAMP WHERE id='guide-linko-0031-tips' AND replace(content_markdown,char(13),'')='Синхронизированный удар использует характеристики Линко. Не считайте её A0 эквивалентом A5: возможность запуска цикла меняется с пробуждениями.' AND json_extract(meta_json,'$.visual') IS NULL;

INSERT OR IGNORE INTO guide_sections (id,guide_id,title,section_type,content_markdown,position,meta_json) SELECT 'zankou-arcs-0035','guide-zankou-0031','Лучшие дуги','best-arcs','',4,'{"visual":{"kind":"arcs","items":[{"id":"zankou-arcs-1","name":"Ravenous Blade","imageUrl":"https://static.nanoka.cc/assets/nte/Game/UI/UI_Icon/Fork/1024/fork_DemonBlade.webp","description":"Даёт 16% критического шанса. Урон Инкантации добавляет по 9% критического урона на 15 секунд, до семи стаков; новый стак появляется не чаще раза в 0,3 секунды.","stats":[{"label":"Атака (ур. 80)","value":"570"},{"label":"Критический шанс (ур. 80)","value":"24%"}],"category":"signature","sourceUrl":"https://www.kaiden.gg/nte/characters/zankou/"},{"id":"zankou-arcs-2","name":"Fluff of Finesse","imageUrl":"https://static.nanoka.cc/assets/nte/Game/UI/UI_Icon/Fork/1024/fork_ThiefCandy.webp","description":"После критического уклонения увеличивает урон носителя на 8% на 10 секунд, до трёх стаков.","stats":[{"label":"Атака (ур. 80)","value":"512"},{"label":"Бонус атаки (ур. 80)","value":"27.5%"}],"category":"replacement","sourceUrl":"https://www.kaiden.gg/nte/characters/zankou/"}]},"reviewedAt":"2026-10-21"}' WHERE EXISTS (SELECT 1 FROM visual_guides_0035 WHERE id='guide-zankou-0031') AND NOT EXISTS (SELECT 1 FROM guide_sections WHERE guide_id='guide-zankou-0031' AND section_type='best-arcs');

INSERT OR IGNORE INTO guide_sections (id,guide_id,title,section_type,content_markdown,position,meta_json) SELECT 'zankou-cartridges-0035','guide-zankou-0031','Лучшие картриджи','cartridges','',5,'{"visual":{"kind":"cartridges","items":[{"id":"zankou-cartridges-1","name":"Crimson: Twin Butterflies","imageUrl":"https://static.nanoka.cc/assets/nte/Game/UI/UI_Icon/kongmu/256/UI_YH_kongmuicon__05.webp","description":"","stats":[{"label":"2 предмета","value":"Урон Инкантации +10%."},{"label":"4 предмета","value":"Когда отряд наносит ближайшему врагу урон Инкантации, носитель получает по 6% атаки, до шести стаков. Каждый длится 10 секунд; эффект работает из резерва."}],"category":"signature","sourceUrl":"https://www.kaiden.gg/nte/characters/zankou/"},{"id":"zankou-cartridges-2","name":"Shadow Creed","imageUrl":"https://static.nanoka.cc/assets/nte/Game/UI/UI_Icon/kongmu/256/UI_YH_kongmuicon__39.webp","description":"","stats":[{"label":"2 предмета","value":"Атака +10%."},{"label":"4 предмета","value":"После навыка увеличивает атаку носителя на 25% на 20 секунд."}],"category":"replacement","sourceUrl":"https://www.kaiden.gg/nte/characters/zankou/"}]},"reviewedAt":"2026-10-21"}' WHERE EXISTS (SELECT 1 FROM visual_guides_0035 WHERE id='guide-zankou-0031') AND NOT EXISTS (SELECT 1 FROM guide_sections WHERE guide_id='guide-zankou-0031' AND section_type='cartridges');

UPDATE guide_sections SET title='Приоритет прокачки навыков',meta_json=json_set(meta_json,'$.visual',json('{"kind":"skills","items":[{"id":"zankou-skills-0","name":"Сверхспособность","description":"Inferno Flamenco — одинаковый приоритет со следующим навыком.","imageUrl":"https://www.kaiden.gg/img/nte/UI/UI_Icon/Skill/Zankou_Ultra.webp","stats":[],"sourceUrl":"https://www.icy-veins.com/neverness-to-everness/zankou-guide-best-builds"},{"id":"zankou-skills-1","name":"Базовая атака","description":"Wildfire — одинаковый приоритет с предыдущим навыком.","imageUrl":"https://www.kaiden.gg/img/nte/UI/UI_Icon/Skill/Zankou_Melee.webp","stats":[],"sourceUrl":"https://www.icy-veins.com/neverness-to-everness/zankou-guide-best-builds"},{"id":"zankou-skills-2","name":"Навык перенаправления","description":"Sanguine Dash","imageUrl":"https://www.kaiden.gg/img/nte/UI/UI_Icon/Skill/Zankou_Skill1.webp","stats":[],"sourceUrl":"https://www.icy-veins.com/neverness-to-everness/zankou-guide-best-builds"},{"id":"zankou-skills-3","name":"Навык поддержки","description":"Stoked Flame","imageUrl":"https://www.kaiden.gg/img/nte/UI/UI_Icon/Skill/Zankou_QTE.webp","stats":[],"sourceUrl":"https://www.icy-veins.com/neverness-to-everness/zankou-guide-best-builds"}]}'),'$.legacyMarkdown',content_markdown),content_markdown='',updated_at=CURRENT_TIMESTAMP WHERE id='guide-zankou-0031-skill-priority' AND replace(content_markdown,char(13),'')='Sanguine Dash → Inferno Flamenco → Wildfire → Stoked Flame — порядок прокачки из Kaiden. В бою важна вся цепочка перехода между формами, а не одна сверхспособность.' AND json_extract(meta_json,'$.visual') IS NULL;

INSERT OR IGNORE INTO guide_sections (id,guide_id,title,section_type,content_markdown,position,meta_json) SELECT 'zankou-stats-0035','guide-zankou-0031','Основные статы','main-stats','',6,'{"visual":{"kind":"stats","items":[{"id":"zankou-stats-0","name":"Бонус урона Инкантации","imageUrl":"","description":"","stats":[]},{"id":"zankou-stats-1","name":"Критический шанс","imageUrl":"","description":"Учитывайте бонусы дуги, консоли и отряда; итоговый шанс не должен превышать 100%.","stats":[]},{"id":"zankou-stats-2","name":"Критический урон","imageUrl":"","description":"","stats":[]},{"id":"zankou-stats-3","name":"Атака %","imageUrl":"","description":"","stats":[]}]},"reviewedAt":"2026-10-21"}' WHERE EXISTS (SELECT 1 FROM visual_guides_0035 WHERE id='guide-zankou-0031') AND NOT EXISTS (SELECT 1 FROM guide_sections WHERE guide_id='guide-zankou-0031' AND section_type='main-stats');

UPDATE guide_sections SET section_type='sources',title='Архив сборки',updated_at=CURRENT_TIMESTAMP WHERE id='guide-zankou-0031-builds' AND replace(content_markdown,char(13),'')='Ravenous Blade — основной выбор; Fluff of Finesse — альтернатива. Картридж Crimson: Twin Butterflies; при его отсутствии рассматривайте Shadow Creed. Модули типа III усиливают критический урон: балансируйте его с шансом критического попадания и атакой.' AND json_extract(meta_json,'$.visual') IS NULL AND EXISTS (SELECT 1 FROM visual_guides_0035 WHERE id='guide-zankou-0031');

UPDATE guide_sections SET title='Базовая ротация',meta_json=json_set(meta_json,'$.visual',json('{"kind":"rotation","items":[{"id":"zankou-rotation-1","name":"Шаг 1","description":"Подготовьте лечение или защиту, усиления Сакири и действия персонажа Хаоса для Горения.","imageUrl":"","stats":[]},{"id":"zankou-rotation-2","name":"Шаг 2","description":"Занку наложите периодический урон в форме Реальности.","imageUrl":"","stats":[]},{"id":"zankou-rotation-3","name":"Шаг 3","description":"Навыком перенаправления перейдите в Иллюзию и проведите её атакующую цепочку.","imageUrl":"","stats":[]},{"id":"zankou-rotation-4","name":"Шаг 4","description":"Успейте выполнить усиленный Soulcross до окончания Иллюзии, чтобы подготовить Bloodfeast Reverie.","imageUrl":"","stats":[]},{"id":"zankou-rotation-5","name":"Шаг 5","description":"Завершите окно через Bloodfeast Reverie и доступную усиленную Inferno Flamenco; затем обновите действия союзников.","imageUrl":"","stats":[]}]}'),'$.legacyMarkdown',content_markdown),content_markdown='',updated_at=CURRENT_TIMESTAMP WHERE id='guide-zankou-0031-rotations' AND replace(content_markdown,char(13),'')='1. Подготовьте лечение или защиту, усиления Сакири и действия персонажа Хаоса для Горения.
2. Занку наложите периодический урон в форме Реальности.
3. Навыком перенаправления перейдите в Иллюзию и проведите её атакующую цепочку.
4. Успейте выполнить усиленный Soulcross до окончания Иллюзии, чтобы подготовить Bloodfeast Reverie.
5. Завершите окно через Bloodfeast Reverie и доступную усиленную Inferno Flamenco; затем обновите действия союзников.' AND json_extract(meta_json,'$.visual') IS NULL;

UPDATE guide_sections SET title='Советы и частые ошибки',content_markdown='Не допускайте окончания Иллюзии до усиленного Soulcross. Прерывание навыка перенаправления срывает смену формы. Для Горения нужен союзник Хаоса; Линко усиливает другой, связанный с последующими атаками аспект команды.',updated_at=CURRENT_TIMESTAMP WHERE id='guide-zankou-0031-tips' AND replace(content_markdown,char(13),'')='Не допускайте окончания Иллюзии до усиленного Soulcross. Прерывание навыка перенаправления срывает смену формы. Для Горения нужен союзник Хаоса; Линко усиливает другой, связанный с последующими атаками аспект команды.' AND json_extract(meta_json,'$.visual') IS NULL;

UPDATE guide_sections SET section_type='sources',title='Архив сборки',updated_at=CURRENT_TIMESTAMP WHERE id='hotori-guide-builds-0012' AND replace(content_markdown,char(13),'')='## Дуга

Marching Beyond Time — сигнатурный вариант; Fluff of Fearlessness — альтернатива. Не сравнивайте варианты без учёта уровня наложения и условий команды.

## Консоль и картриджи

Lost Radiance («Утраченное сияние»): 2 части дают 10% урона Космоса, 4 части — 25% игнорирования защиты на 20 секунд после сверхспособности. Бонус консоли Хотори зависит от модулей типа III.

## Характеристики

Балансируйте шанс и урон критического попадания, бонус Космоса и атаку. При смене дуги меняется потребность в критическом шансе; универсального порога для всех сборок нет. Рекомендации рассчитаны на боевую роль и требуют сверки с выбранной дугой и пробуждениями.' AND json_extract(meta_json,'$.visual') IS NULL AND EXISTS (SELECT 1 FROM visual_guides_0035 WHERE id='guide-hotori');

UPDATE guide_sections SET title='Базовая ротация',meta_json=json_set(meta_json,'$.visual',json('{"kind":"rotation","items":[{"id":"hotori-rotation-1","name":"Шаг 1","description":"Дождитесь достаточного запаса «Незакрытых часов» для навыка Хотори; ресурс накапливается со временем, а не от количества базовых атак.","imageUrl":"","stats":[]},{"id":"hotori-rotation-2","name":"Шаг 2","description":"Примените навык Хотори, открывающий окно записи.","imageUrl":"","stats":[]},{"id":"hotori-rotation-3","name":"Шаг 3","description":"В течение следующих 5 секунд используйте навыки поддержки или перенаправления разных союзников; записывается не более одного действия каждого персонажа.","imageUrl":"","stats":[]},{"id":"hotori-rotation-4","name":"Шаг 4","description":"Подготовьте командные усиления и дождитесь 120 единиц ресурса. Не пытайтесь запустить сверхспособность сразу после записи при неполной шкале.","imageUrl":"","stats":[]},{"id":"hotori-rotation-5","name":"Шаг 5","description":"Активируйте сверхспособность Хотори, чтобы воспроизвести запись и атаковать в остановке времени. Переключение персонажей в этом состоянии недоступно.","imageUrl":"","stats":[]},{"id":"hotori-rotation-6","name":"Шаг 6","description":"После завершения окна вернитесь к действиям союзников и подготовке следующей записи.","imageUrl":"","stats":[]}]}'),'$.legacyMarkdown',content_markdown),content_markdown='',updated_at=CURRENT_TIMESTAMP WHERE id='hotori-guide-rotations-0012' AND replace(content_markdown,char(13),'')='1. Дождитесь достаточного запаса «Незакрытых часов» для навыка Хотори; ресурс накапливается со временем, а не от количества базовых атак.
2. Примените навык Хотори, открывающий окно записи.
3. В течение следующих 5 секунд используйте навыки поддержки или перенаправления разных союзников; записывается не более одного действия каждого персонажа.
4. Подготовьте командные усиления и дождитесь 120 единиц ресурса. Не пытайтесь запустить сверхспособность сразу после записи при неполной шкале.
5. Активируйте сверхспособность Хотори, чтобы воспроизвести запись и атаковать в остановке времени. Переключение персонажей в этом состоянии недоступно.
6. После завершения окна вернитесь к действиям союзников и подготовке следующей записи.' AND json_extract(meta_json,'$.visual') IS NULL;

UPDATE guide_sections SET title='Советы и частые ошибки',content_markdown='- Не путайте три записываемых действия разных союзников с зарядами сигнатурной дуги.
- Сначала откройте окно записи навыком Хотори: действия до него не записываются.
- Повторное применение навыка заменяет предыдущую запись.
